using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CursedPredictionAction", menuName = "Data/Battle/Battle Actions/Moonie/CursedPrediction Action")]
public class CursedPredictionAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PrecisionAction precisionAction;

	[SerializeField]
	private HexAction hexAction;

	public PrecisionAction PrecisionAction => precisionAction;

	public HexAction HexAction => hexAction;

	public override void ActionSelected(int amount)
	{
		base.ActionSelected(amount);
		precisionAction.ResetVariables();
	}

	public override void CastAmount(int amount, GameObject source)
	{
		precisionAction.SetPrecisionActionPlayed();
		precisionAction.DiceSelected(diceList[0]);
		hexAction.CastAmountAction(amount, source, delegate
		{
			precisionAction.Cast(source);
		}, dontEnterChooseActionState: true);
	}
}
